              "id": "checklist_4_24",
              "class": "f_misc",
              "html": "<a href=\"http://darksouls3.wiki.fextralife.com/Lightning+Blade\" target=\"_blank\" rel=\"noopener noreferrer\">Lâmina Relâmpago</a>: Localizado na <a href=\"http://darksouls3.wiki.fextralife.com/Irithyll+Dungeon\" target=\"_blank\" rel=\"noopener noreferrer\">Masmorra de Irithyll</a>"
